import json


def main(env):
    url = "https://api.example.com/tickets"
    resp = None
    for _ in range(3):
        resp = env.http_get(url)
        if 200 <= resp["status"] <= 299:
            break
    else:
        raise RuntimeError(f"unexpected status {resp['status']}")
    data = json.loads(resp["body"])
    open_list = data["open"]
    if not isinstance(open_list, list):
        raise RuntimeError('"open" is not a list')
    count = len(open_list)
    if count > 5:
        return f"escalate {count}"
    return f"{count} open tickets"
